"use client";

import React from "react";
import {
  UseFormRegister,
  UseFormSetValue,
  UseFormWatch,
} from "react-hook-form";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { SeoFieldsSection } from "@/components/shared/SeoFieldsSection";
import { ProjectFormValues } from "./types";
import { useLanguage } from "@/contexts/LanguageContext";
import { Loader2, Save } from "lucide-react";

interface EditLocationTabProps {
  register: UseFormRegister<ProjectFormValues>;
  setValue: UseFormSetValue<ProjectFormValues>;
  watch: UseFormWatch<ProjectFormValues>;
  isSubmitting: boolean;
  onCancel: () => void;
  onSubmit: (e?: React.BaseSyntheticEvent) => Promise<void>;
}

export function EditLocationTab({
  register,
  setValue,
  watch,
  isSubmitting,
  onCancel,
  onSubmit,
}: EditLocationTabProps) {
  const { t } = useLanguage();

  return (
    <form onSubmit={onSubmit} className="space-y-6">
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-5 shadow-xs">
        <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100 border-b border-gray-100 dark:border-neutral-800 pb-3">
          {t("editProject.location.title") || "Location Information"}
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <Label htmlFor="edit-city">
              {t("editProject.location.city") || "City"}
            </Label>
            <Input
              id="edit-city"
              {...register("city_id")}
              placeholder={t("editProject.location.cityPlaceholder") || "e.g. Dubai"}
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-area">
              {t("editProject.location.area") || "Area / District"}
            </Label>
            <Input
              id="edit-area"
              {...register("area_id")}
              placeholder={
                t("editProject.location.areaPlaceholder") ||
                "e.g. Downtown Dubai"
              }
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-landmark">
              {t("editProject.location.landmark") || "Landmark"}
            </Label>
            <Input
              id="edit-landmark"
              {...register("landmark")}
              placeholder={
                t("editProject.location.landmarkPlaceholder") ||
                "e.g. Near Burj Khalifa"
              }
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-google-map-link">
              {t("editProject.location.googleMapLink") || "Google Maps Link"}
            </Label>
            <Input
              id="edit-google-map-link"
              type="url"
              {...register("google_map_link")}
              placeholder={
                t("editProject.location.googleMapPlaceholder") ||
                "https://maps.google.com/..."
              }
              className="mt-1.5"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
          <div>
            <Label htmlFor="edit-latitude">
              {t("editProject.location.latitude") || "Latitude"}
            </Label>
            <Input
              id="edit-latitude"
              type="number"
              step="any"
              {...register("latitude", { valueAsNumber: true })}
              placeholder="25.2048"
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-longitude">
              {t("editProject.location.longitude") || "Longitude"}
            </Label>
            <Input
              id="edit-longitude"
              type="number"
              step="any"
              {...register("longitude", { valueAsNumber: true })}
              placeholder="55.2708"
              className="mt-1.5"
            />
          </div>
        </div>

        <div className="border-t border-gray-100 dark:border-neutral-800 pt-4">
          <h3 className="text-sm font-semibold text-gray-900 dark:text-gray-100 mb-3">
            {t("editProject.location.boundariesTitle") || "Project Boundaries"}
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div>
              <Label htmlFor="edit-north">
                {t("editProject.location.northSide") || "North Side"}
              </Label>
              <Input
                id="edit-north"
                {...register("north_side")}
                placeholder={
                  t("editProject.location.northPlaceholder") ||
                  "e.g. Main Boulevard"
                }
                className="mt-1.5"
              />
            </div>
            <div>
              <Label htmlFor="edit-south">
                {t("editProject.location.southSide") || "South Side"}
              </Label>
              <Input
                id="edit-south"
                {...register("south_side")}
                placeholder={
                  t("editProject.location.southPlaceholder") || "e.g. Park View"
                }
                className="mt-1.5"
              />
            </div>
            <div>
              <Label htmlFor="edit-east">
                {t("editProject.location.eastSide") || "East Side"}
              </Label>
              <Input
                id="edit-east"
                {...register("east_side")}
                placeholder={
                  t("editProject.location.eastPlaceholder") ||
                  "e.g. Canal Access"
                }
                className="mt-1.5"
              />
            </div>
            <div>
              <Label htmlFor="edit-west">
                {t("editProject.location.westSide") || "West Side"}
              </Label>
              <Input
                id="edit-west"
                {...register("west_side")}
                placeholder={
                  t("editProject.location.westPlaceholder") ||
                  "e.g. Highway Connection"
                }
                className="mt-1.5"
              />
            </div>
          </div>
        </div>

        <div className="border-t border-gray-100 dark:border-neutral-800 pt-4">
          <Label htmlFor="edit-location-description">
            {t("editProject.location.description") || "Location Description"}
          </Label>
          <textarea
            id="edit-location-description"
            rows={3}
            {...register("location_description")}
            placeholder={
              t("editProject.location.descriptionPlaceholder") ||
              "e.g. The area is a mix of residential and commercial zones..."
            }
            className="mt-1.5 w-full rounded-md border border-input bg-transparent px-3 py-2 text-sm shadow-xs placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring dark:border-neutral-800"
          />
        </div>
      </div>

      {/* SEO Section */}
      <SeoFieldsSection
        register={register}
        setValue={setValue}
        watch={watch}
        nameFieldName="project_name"
        slugPlaceholder="project-slug"
      />

      {/* Bottom Actions */}
      <div className="flex items-center justify-end gap-3 pt-3">
        <Button
          type="button"
          variant="outline"
          onClick={onCancel}
          disabled={isSubmitting}
          className="dark:border-neutral-700 dark:text-gray-200 px-5"
        >
          {t("editProject.cancel") || t("common.cancel") || "Cancel"}
        </Button>
        <Button
          type="submit"
          disabled={isSubmitting}
          className="bg-[#008081] hover:bg-[#006666] text-white gap-2 shadow-2xs font-medium px-6"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              {t("editProject.updating") || t("common.updating") || "Updating..."}
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              {t("editProject.saveChanges") || "Save Changes"}
            </>
          )}
        </Button>
      </div>
    </form>
  );
}
