"use client";

import React from "react";
import {
  UseFormRegister,
  UseFormSetValue,
  UseFormWatch,
  Control,
  FieldErrors,
  Controller,
} from "react-hook-form";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { RichTextEditor } from "@/components/ui";
import { SeoFieldsSection } from "@/components/shared/SeoFieldsSection";
import { ProjectFormValues } from "./types";
import { useLanguage } from "@/contexts/LanguageContext";
import { Loader2, Save } from "lucide-react";

interface EditBasicInfoTabProps {
  register: UseFormRegister<ProjectFormValues>;
  setValue: UseFormSetValue<ProjectFormValues>;
  watch: UseFormWatch<ProjectFormValues>;
  control: Control<ProjectFormValues>;
  errors: FieldErrors<ProjectFormValues>;
  developersList: any[];
  projectDeveloperName?: string;
  isSubmitting: boolean;
  onCancel: () => void;
  onSubmit: (e?: React.BaseSyntheticEvent) => Promise<void>;
}

export function EditBasicInfoTab({
  register,
  setValue,
  watch,
  control,
  errors,
  developersList,
  projectDeveloperName,
  isSubmitting,
  onCancel,
  onSubmit,
}: EditBasicInfoTabProps) {
  const { t } = useLanguage();

  const statusOptions = [
    {
      label: t("editProject.basicInfo.ongoing") || "Under Construction / Ongoing",
      value: "ongoing",
    },
    {
      label: t("editProject.basicInfo.completed") || "Completed",
      value: "completed",
    },
    {
      label: t("editProject.basicInfo.upcoming") || "Upcoming / Planned",
      value: "upcoming",
    },
  ];

  const projectTypeOptions = [
    {
      label: t("editProject.basicInfo.residential") || "Residential",
      value: "residential",
    },
    {
      label: t("editProject.basicInfo.commercial") || "Commercial",
      value: "commercial",
    },
    {
      label: t("editProject.basicInfo.mixedUse") || "Mixed-use",
      value: "mixed-use",
    },
  ];

  const currencyOptions = [
    {
      label: t("editProject.basicInfo.currencyAed") || "AED (United Arab Emirates Dirham)",
      value: "AED",
    },
    {
      label: t("editProject.basicInfo.currencySar") || "SAR (Saudi Riyal)",
      value: "SAR",
    },
    {
      label: t("editProject.basicInfo.currencyUsd") || "USD (US Dollar)",
      value: "USD",
    },
    {
      label: t("editProject.basicInfo.currencyEgp") || "EGP (Egyptian Pound)",
      value: "EGP",
    },
    {
      label: t("editProject.basicInfo.currencyOmr") || "OMR (Omani Rial)",
      value: "OMR",
    },
  ];

  return (
    <form onSubmit={onSubmit} className="space-y-6">
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-5 shadow-xs">
        <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100 border-b border-gray-100 dark:border-neutral-800 pb-3">
          {t("editProject.basicInfo.title") || "Basic Information"}
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <Label htmlFor="edit-project-name" className="required">
              {t("editProject.basicInfo.projectName") || "Project Name"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Input
              id="edit-project-name"
              placeholder={
                t("editProject.basicInfo.projectNamePlaceholder") ||
                "e.g. Emaar Downtown"
              }
              {...register("project_name", {
                required:
                  t("editProject.basicInfo.projectNameRequired") ||
                  "Project name is required",
              })}
              className="mt-1.5"
              error={!!errors.project_name}
            />
            {errors.project_name && (
              <p className="text-xs text-red-500 mt-1">
                {errors.project_name.message}
              </p>
            )}
          </div>

          <div>
            <Label htmlFor="edit-developer" className="required">
              {t("editProject.basicInfo.developer") || "Developer"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Controller
              name="developer_id"
              control={control}
              rules={{
                required:
                  t("editProject.basicInfo.developerRequired") ||
                  "Developer is required",
              }}
              render={({ field }) => (
                <Select
                  key={`dev-select-${developersList.length}-${field.value || "empty"}`}
                  value={field.value ? String(field.value) : ""}
                  onValueChange={field.onChange}
                >
                  <SelectTrigger
                    className="mt-1.5 bg-white dark:bg-neutral-800"
                    error={!!errors.developer_id}
                  >
                    <SelectValue
                      placeholder={
                        t("editProject.basicInfo.selectDeveloper") ||
                        "Select Developer"
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {developersList.map((developer: any) => {
                      const id = String(
                        developer.developer_id ?? developer.id ?? "",
                      );
                      const name =
                        developer.developer_name ||
                        developer.name ||
                        `Developer ${id}`;
                      return (
                        <SelectItem key={`dev-opt-${id}`} value={id}>
                          {name}
                        </SelectItem>
                      );
                    })}
                    {field.value &&
                      !developersList.some(
                        (d: any) =>
                          String(d.developer_id ?? d.id ?? "") ===
                          String(field.value),
                      ) && (
                        <SelectItem
                          key={`dev-custom-${field.value}`}
                          value={String(field.value)}
                        >
                          {String(
                            projectDeveloperName || `Developer ${field.value}`,
                          )}
                        </SelectItem>
                      )}
                  </SelectContent>
                </Select>
              )}
            />
            {errors.developer_id && (
              <p className="text-xs text-red-500 mt-1">
                {errors.developer_id.message}
              </p>
            )}
          </div>

          <div>
            <Label htmlFor="edit-project-type" className="required">
              {t("editProject.basicInfo.projectType") || "Project Type"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Controller
              name="project_type"
              control={control}
              render={({ field }) => (
                <Select
                  key={`type-select-${field.value || "residential"}`}
                  value={field.value || "residential"}
                  onValueChange={field.onChange}
                >
                  <SelectTrigger className="mt-1.5 bg-white dark:bg-neutral-800">
                    <SelectValue
                      placeholder={
                        t("editProject.basicInfo.selectType") || "Select Type"
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {projectTypeOptions.map((o) => (
                      <SelectItem key={`type-opt-${o.value}`} value={o.value}>
                        {o.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
          </div>

          <div>
            <Label htmlFor="edit-status" className="required">
              {t("editProject.basicInfo.status") || "Status"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Controller
              name="status"
              control={control}
              render={({ field }) => (
                <Select
                  key={`status-select-${field.value || "ongoing"}`}
                  value={field.value || "ongoing"}
                  onValueChange={field.onChange}
                >
                  <SelectTrigger className="mt-1.5 bg-white dark:bg-neutral-800">
                    <SelectValue
                      placeholder={
                        t("editProject.basicInfo.selectStatus") ||
                        "Select Status"
                      }
                    />
                  </SelectTrigger>
                  <SelectContent>
                    {statusOptions.map((o) => (
                      <SelectItem key={`status-opt-${o.value}`} value={o.value}>
                        {o.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
          </div>

          <div>
            <Label htmlFor="edit-currency">
              {t("editProject.basicInfo.currency") || "Currency"}
            </Label>
            <Controller
              name="currency"
              control={control}
              render={({ field }) => (
                <Select
                  key={`curr-select-${field.value || "AED"}`}
                  value={field.value || "AED"}
                  onValueChange={field.onChange}
                >
                  <SelectTrigger className="mt-1.5 bg-white dark:bg-neutral-800">
                    <SelectValue placeholder="Currency" />
                  </SelectTrigger>
                  <SelectContent>
                    {currencyOptions.map((o) => (
                      <SelectItem key={`curr-opt-${o.value}`} value={o.value}>
                        {o.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            />
          </div>
        </div>
      </div>

      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-4 shadow-xs">
        <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100 border-b border-gray-100 dark:border-neutral-800 pb-3">
          {t("editProject.basicInfo.description") || "Project Description"}{" "}
          <span className="text-red-500">*</span>
        </h2>
        <Controller
          name="description"
          control={control}
          render={({ field }) => (
            <RichTextEditor
              content={field.value || ""}
              onChange={field.onChange}
              placeholder={
                t("editProject.basicInfo.descriptionPlaceholder") ||
                "Write full project details and highlights here..."
              }
            />
          )}
        />
      </div>

      <SeoFieldsSection
        register={register}
        setValue={setValue}
        watch={watch}
        nameFieldName="project_name"
        slugPlaceholder="project-slug"
      />

      <div className="flex items-center justify-end gap-3 pt-3">
        <Button
          type="button"
          variant="outline"
          onClick={onCancel}
          disabled={isSubmitting}
          className="dark:border-neutral-700 dark:text-gray-200 px-5"
        >
          {t("editProject.cancel") || t("common.cancel") || "Cancel"}
        </Button>
        <Button
          type="submit"
          disabled={isSubmitting}
          className="bg-[#008081] hover:bg-[#006666] text-white gap-2 shadow-2xs font-medium px-6"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              {t("editProject.updating") || t("common.updating") || "Updating..."}
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              {t("editProject.saveChanges") || "Save Changes"}
            </>
          )}
        </Button>
      </div>
    </form>
  );
}