"use client";

import React from "react";
import {
  UseFormRegister,
  UseFormSetValue,
  UseFormWatch,
  FieldErrors,
} from "react-hook-form";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { SeoFieldsSection } from "@/components/shared/SeoFieldsSection";
import { ProjectFormValues } from "./types";
import { useLanguage } from "@/contexts/LanguageContext";
import { Loader2, Save } from "lucide-react";
import dynamic from "next/dynamic";

const UnitsTab = dynamic(
  () => import("../../../[id]/components/tabs/UnitsTab").then((mod) => mod.UnitsTab),
  { ssr: false },
);

interface EditUnitsPricingTabProps {
  register: UseFormRegister<ProjectFormValues>;
  setValue: UseFormSetValue<ProjectFormValues>;
  watch: UseFormWatch<ProjectFormValues>;
  errors: FieldErrors<ProjectFormValues>;
  properties: any[];
  isSubmitting: boolean;
  onCancel: () => void;
  onSubmit: (e?: React.BaseSyntheticEvent) => Promise<void>;
}

export function EditUnitsPricingTab({
  register,
  setValue,
  watch,
  errors,
  properties,
  isSubmitting,
  onCancel,
  onSubmit,
}: EditUnitsPricingTabProps) {
  const { t } = useLanguage();
  const currency = watch("currency") || "AED";

  return (
    <form onSubmit={onSubmit} className="space-y-6">
      {/* Units & Dimensions */}
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-5 shadow-xs">
        <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100 border-b border-gray-100 dark:border-neutral-800 pb-3">
          {t("editProject.unitsPricing.unitsDimensionsTitle") || "Units & Dimensions"}
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <Label htmlFor="edit-total-units">
              {t("editProject.unitsPricing.totalUnits") || "Total Units"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Input
              id="edit-total-units"
              type="number"
              {...register("total_units", {
                required:
                  t("editProject.unitsPricing.totalUnitsRequired") ||
                  "Total units is required",
              })}
              placeholder={t("editProject.unitsPricing.totalUnits") || "Total units"}
              className="mt-1.5"
              error={!!errors.total_units}
            />
            {errors.total_units && (
              <p className="text-xs text-red-500 mt-1">
                {errors.total_units.message}
              </p>
            )}
          </div>

          <div>
            <Label htmlFor="edit-available-units">
              {t("editProject.unitsPricing.availableUnits") || "Available Units"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Input
              id="edit-available-units"
              type="number"
              {...register("available_units", {
                required:
                  t("editProject.unitsPricing.availableUnitsRequired") ||
                  "Available units is required",
              })}
              placeholder={
                t("editProject.unitsPricing.availableUnits") || "Available units"
              }
              className="mt-1.5"
              error={!!errors.available_units}
            />
            {errors.available_units && (
              <p className="text-xs text-red-500 mt-1">
                {errors.available_units.message}
              </p>
            )}
          </div>

          <div>
            <Label htmlFor="edit-project-size">
              {t("editProject.unitsPricing.projectSize") || "Project Size"}
            </Label>
            <Input
              id="edit-project-size"
              {...register("project_size")}
              placeholder={
                t("editProject.unitsPricing.projectSizePlaceholder") ||
                "e.g. 50,000 sqm"
              }
              className="mt-1.5"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 pt-2">
          <div>
            <Label htmlFor="edit-launch-date">
              {t("editProject.unitsPricing.launchDate") || "Launch Date"}{" "}
              <span className="text-red-500">*</span>
            </Label>
            <Input
              id="edit-launch-date"
              type="date"
              {...register("launch_date", {
                required:
                  t("editProject.unitsPricing.launchDateRequired") ||
                  "Launch date is required",
              })}
              className="mt-1.5"
              error={!!errors.launch_date}
            />
            {errors.launch_date && (
              <p className="text-xs text-red-500 mt-1">
                {errors.launch_date.message}
              </p>
            )}
          </div>

          <div>
            <Label htmlFor="edit-completion-date">
              {t("editProject.unitsPricing.completionDate") || "Completion Date"}
            </Label>
            <Input
              id="edit-completion-date"
              type="date"
              {...register("completion_date")}
              className="mt-1.5"
            />
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-2">
          <div>
            <Label htmlFor="edit-permit-no">
              {t("editProject.unitsPricing.permitNo") || "Permit No"}
            </Label>
            <Input
              id="edit-permit-no"
              {...register("permit_no")}
              placeholder="e.g. 447"
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-phase">
              {t("editProject.unitsPricing.phase") || "Phase"}
            </Label>
            <Input
              id="edit-phase"
              {...register("phase")}
              placeholder="e.g. 55"
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-barcode">
              {t("editProject.unitsPricing.barcode") || "Barcode"}
            </Label>
            <Input
              id="edit-barcode"
              {...register("barcode")}
              placeholder="e.g. 77"
              className="mt-1.5"
            />
          </div>
        </div>
      </div>

      {/* Pricing Range */}
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 space-y-5 shadow-xs">
        <h2 className="text-base font-semibold text-gray-900 dark:text-gray-100 border-b border-gray-100 dark:border-neutral-800 pb-3">
          {t("editProject.unitsPricing.pricingRangeTitle") || "Pricing Range"}
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <Label htmlFor="edit-min-price">
              {t("editProject.unitsPricing.minPrice") || "Min Price"} ({currency})
            </Label>
            <Input
              id="edit-min-price"
              type="number"
              {...register("min_price")}
              placeholder={
                t("editProject.unitsPricing.minPricePlaceholder") ||
                "e.g. 1000000"
              }
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-max-price">
              {t("editProject.unitsPricing.maxPrice") || "Max Price"} ({currency})
            </Label>
            <Input
              id="edit-max-price"
              type="number"
              {...register("max_price")}
              placeholder={
                t("editProject.unitsPricing.maxPricePlaceholder") ||
                "e.g. 5000000"
              }
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-price-sq-min">
              {t("editProject.unitsPricing.priceSqMin") || "Min Price / SQ"} ({currency})
            </Label>
            <Input
              id="edit-price-sq-min"
              type="number"
              {...register("price_sq_min")}
              placeholder={
                t("editProject.unitsPricing.priceSqMinPlaceholder") ||
                "e.g. 1500"
              }
              className="mt-1.5"
            />
          </div>
          <div>
            <Label htmlFor="edit-price-sq-max">
              {t("editProject.unitsPricing.priceSqMax") || "Max Price / SQ"} ({currency})
            </Label>
            <Input
              id="edit-price-sq-max"
              type="number"
              {...register("price_sq_max")}
              placeholder={
                t("editProject.unitsPricing.priceSqMaxPlaceholder") ||
                "e.g. 3500"
              }
              className="mt-1.5"
            />
          </div>
        </div>
      </div>

      {/* Properties / Units List */}
      <div className="bg-white dark:bg-neutral-900 rounded-xl border border-gray-200 dark:border-neutral-800 p-5 sm:p-6 shadow-xs">
        <UnitsTab properties={properties} currency={currency} />
      </div>

      {/* SEO Section */}
      <SeoFieldsSection
        register={register}
        setValue={setValue}
        watch={watch}
        nameFieldName="project_name"
        slugPlaceholder="project-slug"
      />

      {/* Bottom Actions */}
      <div className="flex items-center justify-end gap-3 pt-3">
        <Button
          type="button"
          variant="outline"
          onClick={onCancel}
          disabled={isSubmitting}
          className="dark:border-neutral-700 dark:text-gray-200 px-5"
        >
          {t("editProject.cancel") || t("common.cancel") || "Cancel"}
        </Button>
        <Button
          type="submit"
          disabled={isSubmitting}
          className="bg-[#008081] hover:bg-[#006666] text-white gap-2 shadow-2xs font-medium px-6"
        >
          {isSubmitting ? (
            <>
              <Loader2 className="h-4 w-4 animate-spin" />
              {t("editProject.updating") || t("common.updating") || "Updating..."}
            </>
          ) : (
            <>
              <Save className="h-4 w-4" />
              {t("editProject.saveChanges") || "Save Changes"}
            </>
          )}
        </Button>
      </div>
    </form>
  );
}
